    "Põe o som de fábrica de cada momento que ainda está sem som: destaque entrando, aviso entrando, likômetro e QR Code entrando e saindo, dado rolando e timer zerando. O que você já escolheu fica.": "아직 소리가 없는 순간마다 기본 소리를 넣습니다: 하이라이트 등장, 알림 등장, 좋아요 미터와 QR 코드의 등장·퇴장, 주사위 굴러감, 타이머 0. 이미 고른 것은 그대로입니다.",
    "Todos os momentos com som de fábrica já têm som — nada mudou.": "기본 소리가 있는 순간은 모두 이미 소리가 있습니다. 바뀐 것이 없습니다.",
    "Sons de fábrica aplicados nos momentos que estavam vazios:": "비어 있던 순간에 기본 소리를 넣었습니다:",
