    "Escolha primeiro a ação da tecla — o emoji pelo estado depende dela.": "먼저 키의 동작을 고르세요. 상태별 이모지는 그것에 따라 달라집니다.",
    "🟢 Ligado / no ar / som ativo": "🟢 켜짐 / 방송 중 / 소리 켜짐",
    "🔴 No preview / mudo": "🔴 미리보기 / 음소거",
    "⚪ Desligado": "⚪ 꺼짐",
    "O contorno continua mudando de cor; a cara muda junto. Sem o programa conectado, fica o emoji de sempre.": "테두리 색은 계속 바뀌고, 얼굴도 함께 바뀝니다. 프로그램이 연결되지 않으면 평소 이모지가 유지됩니다.",
    "Um emoji para cada cor do contorno: 🟢 verde = ligado, no ar ou som ativo; 🔴 vermelho = no preview ou mudo; ⚪ apagado. Caixa vazia = fica o emoji de sempre.": "테두리 색마다 이모지 하나: 🟢 초록 = 켜짐, 방송 중 또는 소리 켜짐; 🔴 빨강 = 미리보기 또는 음소거; ⚪ 꺼짐. 빈칸이면 평소 이모지가 유지됩니다.",
    "O contorno da tecla fica verde quando o que ela controla está ligado (no ar, gravando, som ativo) e vermelho no preview ou no mudo. Com «Automático» ou «Eu escolho», o emoji também muda com o estado (🎙️ ativo / 🔇 mudo).": "키 테두리는 제어 대상이 켜져 있을 때(방송 중, 녹화 중, 소리 켜짐) 초록이 되고, 미리보기나 음소거일 때 빨강이 됩니다. «자동» 또는 «내가 고름»이면 이모지도 상태에 따라 바뀝니다(🎙️ 켜짐 / 🔇 음소거).",
    "🎙️ Silenciar/liberar o áudio": "🎙️ 오디오 음소거/해제",
