    "Só a conversa direta está entrando — ligue os grupos acima para usar este campo.": "1:1 대화만 들어오고 있습니다 — 이 칸을 쓰려면 위에서 그룹을 켜세요.",
    // 🎙️ v0.140: a transcrição na região do comentário
