    "📱 O código em si": "📱 코드 자체",
    "As cores acima são do cartão que segura o QR; estas aqui são do código em si. Nada disto muda o que o QR carrega — só o desenho.": "위의 색은 QR을 담는 카드의 것이고, 여기 색은 코드 자체의 것입니다. 어느 것도 QR이 담은 내용을 바꾸지 않습니다 — 그림만 바뀝니다.",
