    "Os três cantos usam a mesma cor dos quadradinhos": "세 모서리는 네모와 같은 색을 씁니다",
    "Cor do fundo do código": "코드 배경색",
    "Opacidade do fundo do código:": "코드 배경의 불투명도:",
    "Margem em volta:": "둘레 여백:",
    "quadradinhos": "네모",
    "Folga entre os quadradinhos:": "네모 사이 간격:",
    "⚠️ Sem fundo: o QR fica por conta do cenário atrás. Se a cena for escura ou agitada, os celulares não leem. Deixe o cartão do widget com fundo, ou ponha o QR sobre uma área clara e parada.": "⚠️ 배경 없음: QR이 뒤 화면에 좌우됩니다. 장면이 어둡거나 산만하면 휴대폰이 읽지 못합니다. 위젯 카드에 배경을 남기거나, 밝고 움직임 없는 자리에 QR을 두세요.",
    "⚠️ Invertido: os quadradinhos estão mais claros que o fundo. Muitos celulares não leem assim — o esperado é escuro sobre claro.": "⚠️ 반전: 네모가 배경보다 밝습니다. 이렇게는 못 읽는 휴대폰이 많습니다 — 밝은 바탕에 어두운 네모가 기본입니다.",
    "⚠️ Pouco contraste: abaixo de 4:1 a leitura começa a falhar. Escureça os quadradinhos ou clareie o fundo.": "⚠️ 대비 부족: 4:1 아래로 내려가면 인식이 흔들립니다. 네모를 어둡게 하거나 배경을 밝게 하세요.",
    "⚠️ Margem pequena: o QR precisa de uma faixa vazia em volta. Menos de 2 quadradinhos atrapalha a leitura (a norma pede 4).": "⚠️ 여백이 좁음: QR 둘레에는 빈 띠가 필요합니다. 네모 2개보다 좁으면 인식을 방해합니다(규격은 4개).",
    "⚠️ Folga alta: os quadradinhos ficam finos demais e o celular pode se perder.": "⚠️ 간격이 큼: 네모가 너무 가늘어져 휴대폰이 놓칠 수 있습니다.",
    "✅ Contraste e margem em ordem — deve escanear numa boa.": "✅ 대비와 여백 모두 괜찮습니다 — 무난하게 스캔될 겁니다.",
    // 🧪 v0.137: apagar os comentários de teste
    "Apagar todos os comentários de teste (e as fichas que eles criaram no sorteio)": "테스트 댓글을 모두 지우기 (추첨에 만들어진 응모권까지)",
    // 🏷️ v0.136: o crédito de fonte da 🎞️ Mídia direta
