    "O que aparece embaixo da mídia na tela do público. Vem preenchido pelo endereço, e você escreve o que quiser.": "시청자 화면에서 미디어 아래에 나오는 글입니다. 주소를 보고 채워져 오며, 원하는 대로 고쳐 쓸 수 있습니다.",
    "Fonte: @perfil · site.com": "출처: @계정 · site.com",
    // 🚫 v0.135: sites que não aceitam ser abertos dentro de um quadro
    "🚫 Este site não deixa a página dele aparecer dentro de um quadro — é uma regra do próprio site, não do OBS Social. Para mostrar o vídeo dele, ligue o 🎬 extrator em Configurações → 🧪 Labs, ou baixe o arquivo e use o 📂 Procurar aqui de cima.": "🚫 이 사이트는 자기 페이지가 틀 안에 나오는 것을 허용하지 않습니다 — 사이트 자체의 규칙이지 OBS Social의 문제가 아닙니다. 영상을 보여 주려면 설정 → 🧪 Labs에서 🎬 추출기를 켜거나, 파일을 내려받아 위의 📂 찾아보기를 쓰세요.",
    "🚫 Este site não deixa a página dele aparecer dentro de um quadro.": "🚫 이 사이트는 자기 페이지가 틀 안에 나오는 것을 허용하지 않습니다.",
    // 🎬 v0.134: o extrator opcional da 🎞️ Mídia direta (yt-dlp)
    "🎬 Extrator da mídia direta (experimental)": "🎬 다이렉트 미디어 추출기 (실험적)",
