    "Não consegui ler esse arquivo de tema. Ele precisa ser um tema salvo pelo OBS Social.": "그 테마 파일을 읽을 수 없었어요. OBS Social에서 저장한 테마여야 해요.",
    "Carregar este tema? Ele substitui as cores e os ajustes de aparência que estão valendo agora.": "이 테마를 불러올까요? 지금 적용된 색상과 외형 설정을 대체해요.",
