    '🗄️ Mexer nos logs': '🗄️ 로그 관리',
    'Assistir ao painel é sempre permitido; o resto só funciona com o seletor ligado. Quem entrar com a senha abaixo ignora os seletores e controla tudo.':
      '대시보드 보기는 항상 허용돼요; 나머지는 스위치가 켜져 있어야 작동해요. 아래 비밀번호로 로그인한 사람은 스위치와 상관없이 전부 제어할 수 있어요.',
    '🔑 Senha de acesso pela rede (opcional) —': '🔑 네트워크 접속 비밀번호(선택) —',
    'Com senha, quem abre o painel pela rede pode entrar com ela e aí controla tudo (os seletores acima valem para quem NÃO entrou). A senha vira um código embaralhado (hash) — nunca fica gravada em texto. Só este computador pode definir, trocar ou remover.':
      '비밀번호를 설정하면 네트워크로 대시보드를 여는 사람이 그것으로 로그인해서 전부 제어할 수 있어요(위 스위치는 로그인하지 않은 사람에게 적용돼요). 비밀번호는 해시로 변환돼요 — 절대 평문으로 저장되지 않아요. 이 컴퓨터에서만 설정, 변경, 삭제할 수 있어요.',
    'senha atual (para trocar/remover)': '현재 비밀번호(변경/삭제용)',
