    // ---------- mensagens do servidor que aparecem na interface ----------
    'A Bilibili é experimental — ative em Configurações → 🧪 Labs para usar.': 'Bilibili는 실험 기능이에요 — 사용하려면 설정 → 🧪 Labs에서 켜세요.',
    'O OBS Social só aceita conexões da rede local.': 'OBS Social은 로컬 네트워크의 연결만 허용해요.',
    'Modo restrito: uploads desativados pelo streamer.': '제한 모드: 스트리머가 업로드를 비활성화했어요.',
    'Origem não permitida.': '허용되지 않은 출처예요.',
    'Modo restrito: doações só do computador do streamer.': '제한 모드: 후원은 스트리머의 컴퓨터에서만 가능해요.',
    'Doações estão desativadas. Ligue em Configurações → 🧪 Labs.': '후원이 꺼져 있어요. 설정 → 🧪 Labs에서 켜세요.',
    'Muitas tentativas. Espere alguns minutos.': '시도가 너무 많아요. 몇 분 기다려 주세요.',
    'A senha atual não confere.': '현재 비밀번호가 맞지 않아요.',
    'Arquivo grande demais (limite: 300 MB).': '파일이 너무 커요(한도: 300 MB).',
    'Falha ao gravar o arquivo.': '파일 저장에 실패했어요.',
    'Não encontrado': '찾을 수 없음',
    'Conecte o YouTube primeiro (na engrenagem).': '먼저 YouTube를 연결하세요(톱니바퀴에서).',
    'Não consegui ler os números (a live está no ar?)': '숫자를 읽지 못했어요(방송이 켜져 있나요?)',
    'YouTube não devolveu os números': 'YouTube가 숫자를 돌려주지 않았어요',
    'não consegui ler o número de espectadores (formato mudou?)': '시청자 수를 읽지 못했어요(형식이 바뀌었나요?)',
    'consulta recusada': '조회가 거부됐어요',
    'erro desconhecido': '알 수 없는 오류',
    'tempo esgotado (60s)': '시간 초과(60초)',
    'o GitHub respondeu': 'GitHub 응답:',
    'arquivo baixado não é um ZIP válido': '다운로드한 파일이 올바른 ZIP이 아니에요',
    'não achei o package.json na atualização': '업데이트에서 package.json을 찾지 못했어요',
    '— o pacote de atualização não está acessível agora. Tente de novo mais tarde.': '— 지금은 업데이트 패키지에 접근할 수 없어요. 나중에 다시 시도하세요.',
    '— parece um antivírus/firewall com "inspeção HTTPS" interceptando a conexão. Atualize o Node.js para a versão LTS mais nova em nodejs.org (aí o programa passa a confiar nos certificados do Windows) ou desative a inspeção HTTPS do antivírus para o Node.':
      '— "HTTPS 검사"를 하는 백신/방화벽이 연결을 가로채는 것 같아요. nodejs.org에서 Node.js를 최신 LTS 버전으로 업데이트하거나(그러면 프로그램이 Windows 인증서를 신뢰하게 돼요), 백신의 Node용 HTTPS 검사를 끄세요.',

