    "O botão 🖱️ do painel abre esta página direto. Tudo salva sozinho e muda na tela na hora, até no meio da live. O 🧪 coloca um comentário de exemplo no ar para você ver o destaque — ele aparece no OBS também, então tire do ar antes de ir para a live.": "패널의 🖱️ 버튼으로 이 페이지를 바로 열 수 있습니다. 모든 것이 자동 저장되고 방송 중에도 화면에 즉시 반영됩니다. 🧪 는 강조 표시를 볼 수 있게 예시 댓글을 방송에 올립니다 — OBS에도 나타나니 방송 전에 내려 주세요.",

