    "Deixe o OBS Social com a sua cara: cores, imagem de fundo, tamanhos de texto e de ícones, cantos e espaçamento. Isto muda o": "OBS Social을 내 스타일로: 색상, 배경 이미지, 글자·아이콘 크기, 모서리와 여백. 바뀌는 곳은",
    "painel e as configurações": "패널과 설정",
    "— e, com o 🖥️ abaixo ligado, os": "— 그리고 아래 🖥️를 켜면",
    "overlays da live": "방송 오버레이",
    "vestem o tema junto. O": "도 테마를 입습니다.",
    "(no painel) continua funcionando por cima disto, para aumentar tudo de uma vez.": "(패널의)는 그 위에서 계속 작동해 전체를 한 번에 키웁니다.",
    "Vestir também os overlays da live": "방송 오버레이에도 입히기",
    "— ao carregar um tema, o cartão do destaque, o chat fixo e os widgets ganham as cores, os cantos e a fonte dele (o QR mantém o fundo branco, para continuar escaneável)": "— 테마를 불러오면 강조 카드, 고정 채팅, 위젯이 그 색·모서리·글꼴을 받습니다(QR은 스캔되도록 흰 배경 유지)",
    "Acessibilidade": "접근성",
    "♿ Acessibilidade": "♿ 접근성",
    "Recursos para o OBS Social funcionar bem para todo mundo. Cada um tem o seu liga/desliga e vale no": "OBS Social이 모두에게 잘 작동하도록 하는 기능들. 각자 스위치가 있고 적용되는 곳은",
    "painel e nas configurações": "패널과 설정",
    "na hora, em todos os aparelhos conectados. Os overlays do OBS (o conteúdo que o público vê) ficam como você desenhou.": "즉시, 연결된 모든 기기에서. OBS 오버레이(시청자가 보는 콘텐츠)는 디자인한 그대로입니다.",
    "Contraste reforçado": "강한 대비",
    "— textos secundários e bordas deixam de ser suaves; links ganham sublinhado": "— 보조 텍스트와 테두리가 뚜렷해지고 링크에 밑줄이 생깁니다",
    "Para baixa visão. Combina com o tema ⚡ Alto contraste da aba 🎨 Temas (preto + amarelo), que muda as cores da interface inteira.": "저시력용. 🎨 테마 탭의 ⚡ 고대비 테마(검정+노랑)와 함께 쓰면 인터페이스 전체 색이 바뀝니다.",
    "Reduzir animações": "애니메이션 줄이기",
    "— corta as animações e transições da interface": "— 인터페이스의 애니메이션과 전환을 끕니다",
    "Para quem tem sensibilidade a movimento (enjoo, epilepsia fotossensível, TDAH). As animações do overlay na live não mudam — elas são parte do seu show.": "움직임에 민감한 분들을 위해(멀미, 광과민성 뇌전증, ADHD). 방송 중 오버레이 애니메이션은 그대로 — 쇼의 일부니까요.",
    "Foco visível reforçado": "뚜렷한 포커스",
    "— um anel grosso mostra onde você está ao navegar por Tab": "— Tab으로 이동할 때 위치를 굵은 고리로 표시",
    "Para quem usa o teclado em vez do mouse (mobilidade reduzida, leitores de tela).": "마우스 대신 키보드를 쓰는 분들을 위해(이동 제약, 스크린 리더).",
    "Formas além de cor no status": "상태에 색 이외의 모양도",
    "— a bolinha das conexões ganha ✓ (live no ar), ! (sem live) e ✕ (falhou)": "— 연결 점에 ✓(방송 중), !(방송 없음), ✕(실패)가 붙습니다",
    "Para daltonismo: verde, amarelo e vermelho deixam de ser a única pista.": "색각 이상용: 초록·노랑·빨강만이 단서가 아니게 됩니다.",
    "💡 Também ajudam (já existem em outras abas)": "💡 이것들도 도움이 됩니다(다른 탭에 이미 있음)",
    "(no painel) amplia tudo de uma vez; o": "(패널의)는 전체를 한 번에 확대;",
    "Tamanho dos textos": "글자 크기",
    "e a": "와",
    "fonte": "글꼴",
    "ficam na aba 🎨 Temas; os avisos importantes aparecem como texto (nunca só como som); e as dicas dos botões são lidas por leitores de tela. Falta algo para você? Conte na aba 📣 Feedback — acessibilidade é prioridade.": "은 🎨 테마 탭에 있습니다. 중요한 경고는 항상 텍스트로 표시(소리로만 알리지 않음), 버튼 팁은 스크린 리더가 읽습니다. 부족한 게 있나요? 📣 피드백 탭에 알려주세요 — 접근성은 우선순위입니다.",
    "A conexão falhou": "연결에 실패했습니다",
    "🎁 Resultado do sorteio": "🎁 추첨 결과",
    "O pódio também está na tela do OBS (widget 🎁). Fechar aqui não tira de lá.": "시상대는 OBS 화면에도 있습니다(🎁 위젯). 여기서 닫아도 거기선 사라지지 않습니다.",
    "Fechar este aviso aqui (a tela do OBS continua como está)": "이 알림을 여기서 닫기(OBS 화면은 그대로)",

