    "8 alças": "8개의 핸들",
    "para mudar o tamanho — os números aparecem ao vivo, na mesma unidade dos seletores manuais. O 📺": "크기를 바꾸려면 — 숫자가 수동 선택기와 같은 단위로 실시간 표시됩니다. 📺",
