    "também mora aqui (ele é a URL própria dele no OBS, então a prévia não o desenha — mas a posição e o tamanho valem de verdade). Seu overlay enviado (moldura de tela inteira) aparece como 🖼️.": "도 여기에 삽니다(OBS에서는 자체 URL이라 미리보기에는 그려지지 않지만, 위치와 크기는 실제로 적용됩니다). 업로드한 오버레이(전체 화면 프레임)는 🖼️로 표시.",
