    "que chega": "도착하는 댓글뿐",
    "anima — os que já estavam na tela ficam parados. Com ♿ Acessibilidade → Sem animações ligado, nada anima.": "— 이미 화면에 있는 것들은 가만히 있습니다. ♿ 접근성 → 애니메이션 없음이 켜져 있으면 아무것도 움직이지 않습니다.",
    "Tudo apagado: o OBS Social voltou ao padrão de fábrica e vai REINICIAR sozinho em instantes (pelo mesmo caminho da atualização). Esta página recarrega quando ele voltar.": "모두 삭제됨: OBS Social이 공장 기본값으로 돌아갔고 곧 스스로 재시작합니다(업데이트와 같은 경로로). 돌아오면 이 페이지가 새로고침됩니다.",
    "Ao terminar, o programa REINICIA sozinho (como na atualização)": "끝나면 프로그램이 스스로 재시작합니다(업데이트처럼)",
    "Este é o MESMO pódio da tela do OBS (widget 🎁), com o mesmo dado 🎲 e as mesmas configurações — o suspense aqui é o do seu público. Fechar no ✖ acima não tira da tela.": "이것은 OBS 화면과 같은 시상대입니다(🎁 위젯). 같은 주사위 🎲, 같은 설정 — 여기의 긴장감은 시청자의 것과 같습니다. 위의 ✖는 여기서만 닫고 화면에서는 지우지 않습니다.",
    "✖ Tirar o pódio da tela": "✖ 시상대를 화면에서 내리기",
    "Tirar o pódio da tela do OBS (o mesmo botão da ferramenta 🎁)": "시상대를 OBS 화면에서 내리기(🎁 도구와 같은 버튼)",
    "Organizar a tela: posições, tamanhos e mídias (abre as configurações, aba 🎨 Temas)": "화면 배치: 위치·크기·미디어(설정의 🎨 테마 탭을 엽니다)",
    "Escreva um recado para aparecer na tela da live. A aparência (fonte, cores, tamanho, animações) fica em": "방송 화면에 나타날 메시지를 쓰세요. 모양(글꼴, 색, 크기, 애니메이션)은 여기에:",
    "Configurações → 🎨 Temas": "설정 → 🎨 테마",
    "O fuso horário fica em": "시간대는 여기에:",
    "Estas opções também estão em Configurações → 🎨 Temas, junto da escolha do som.": "이 옵션들은 설정 → 🎨 테마, 소리 선택 옆에도 있습니다.",
    "Se o ⏳ Timer estiver combinado com os Avisos, o recado sai sozinho quando o tempo acabar.": "⏳ 타이머가 공지와 연동되어 있으면 시간이 끝날 때 메시지가 저절로 내려갑니다.",
    "⏱️ Cronômetro": "⏱️ 스톱워치",
    "⌛ Quando o tempo acabar": "⌛ 시간이 끝나면",
    "📢 Piscar o Aviso nos 10 segundos finais": "📢 마지막 10초에 공지 깜빡이기",
    "Som só na live": "소리는 방송에서만",
    "Som só no meu computador": "소리는 내 컴퓨터에서만",
    "Som no painel e na live": "소리는 패널과 방송 모두",
    "Tempo do timer": "타이머 시간",
    "vitórias": "승",
    "Vitórias (dá para digitar)": "승수(입력 가능)",
    "Recorde (dá para digitar)": "기록(입력 가능)",
    "+1 vitória (segure para ir mais rápido)": "+1승(누르고 있으면 빨라짐)",
    "Tirar 1 vitória (segure para ir mais rápido)": "1승 빼기(누르고 있으면 빨라짐)",
    "+1 no recorde (segure para ir mais rápido)": "기록에 +1(누르고 있으면 빨라짐)",
    "Tirar 1 do recorde — para corrigir quando você adiciona sem querer (segure para ir mais rápido)": "기록에서 1 빼기 — 실수로 더했을 때 고치는 용도(누르고 있으면 빨라짐)",
    "Relógio, cronômetro e timer": "시계·스톱워치·타이머",
    "Ex.: Voltamos em 5 minutos! Já já tem sorteio 🎁": "예: 5분 뒤에 돌아올게요! 곧 추첨 🎁",
