    "Quantos botões por página — nas configurações e no painel": "페이지당 버튼 수 — 설정과 패널 모두에서",
    "A fonte do texto de TODOS os botões (como no Stream Deck)": "모든 버튼의 텍스트 글꼴(Stream Deck처럼)",
