    "A tecla vai fazer:": "이 키가 할 일:",
    "escolha a ação do OBS no editor": "편집기에서 OBS 동작을 고르세요",
    "Manda esta ação para o OBS agora mesmo": "이 동작을 지금 바로 OBS로 보냅니다",
    "Conecte o 🎬 OBS Studio ali em cima para testar": "테스트하려면 위의 🎬 OBS Studio를 연결하세요",
    "A escala do OBS vai de -100 dB (mudo) a +26 dB. 0 dB é o volume cheio da fonte.": "OBS의 눈금은 -100 dB(무음)부터 +26 dB까지입니다. 0 dB가 소스의 최대 음량입니다.",
    "Em milissegundos (1000 = 1 segundo). 0 = não mexe na duração que já está no OBS.": "밀리초 단위(1000 = 1초). 0 = OBS에 설정된 길이를 그대로 둡니다.",
    "Escolha o que esta tecla faz no OBS. As listas de cenas, fontes e filtros vêm do OBS conectado — sem conexão, dá para digitar o nome na mão.": "이 키가 OBS에서 무엇을 할지 고르세요. 장면·소스·필터 목록은 연결된 OBS에서 옵니다 — 연결이 없어도 이름을 직접 입력할 수 있습니다.",
    "🎵 toca um som · 🎬 Ação do OBS: comanda o OBS Studio (gravar, trocar de cena, mudo...) · 🎛️ Botão de multi ação: guarda teclas e o clique toca tudo em fila (segurar abre) · 📁 Pasta simples: só guarda teclas — o clique abre, nada toca": "🎵 소리를 재생 · 🎬 OBS 동작: OBS Studio를 제어(녹화, 장면 전환, 음소거...) · 🎛️ 멀티 액션 버튼: 키를 담고 클릭하면 줄줄이 모두 재생(길게 누르면 열림) · 📁 단순 폴더: 키만 담음 — 클릭하면 열리고 아무것도 재생되지 않음",
    // ---------- v0.53: controle do OBS no painel, Labs e FAQ ----------
    "🎭 Modo estúdio e transição": "🎭 스튜디오 모드와 전환 효과",
