    "Marcador de capítulo na gravação (OBS 30.2+, gravação Hybrid MP4)": "녹화에 챕터 표시(OBS 30.2+, Hybrid MP4 녹화)",
    "Ligar/desligar a câmera virtual": "가상 카메라 켜기/끄기",
    "Ligar/desligar o replay buffer": "리플레이 버퍼 켜기/끄기",
    "Salvar o replay dos últimos segundos": "최근 몇 초의 리플레이 저장",
    "Print da cena no ar — cai direto nas mídias do programa": "송출 중인 장면 캡처 — 바로 프로그램 미디어로 들어갑니다",
    "⏺ gravação PAUSADA": "⏺ 녹화 일시정지됨",
    "📷 câmera virtual ligada": "📷 가상 카메라 켜짐",
    "⏪ replay buffer ligado": "⏪ 리플레이 버퍼 켜짐",
    "Desligar a câmera virtual do OBS?": "OBS 가상 카메라를 끌까요?",
    "Ligar a câmera virtual do OBS?": "OBS 가상 카메라를 켤까요?",
    "não sei o que capturar: o OBS não tem cena no ar": "무엇을 캡처할지 모르겠습니다: OBS에 송출 중인 장면이 없습니다",
    "print vazio ou grande demais": "캡처가 비었거나 너무 큽니다",
    "replay salvo pelo OBS": "OBS가 리플레이를 저장했습니다",
    "o replay buffer está desligado — ligue antes de salvar": "리플레이 버퍼가 꺼져 있습니다 — 저장하기 전에 켜세요",
    "marcador de capítulo pede OBS 30.2 ou mais novo": "챕터 표시는 OBS 30.2 이상이 필요합니다",
    "o preview só existe com o modo estúdio ligado": "미리보기는 스튜디오 모드가 켜져 있어야 있습니다",
    "a transição de estúdio pede o modo estúdio ligado": "스튜디오 전환은 스튜디오 모드가 켜져 있어야 합니다",
    "🎛️ O que aparece no controle do OBS dentro do painel": "🎛️ 패널의 OBS 제어에 무엇을 보일지",
    "Marque só o que você usa. Isso muda a ferramenta 🎬 do painel — as teclas 🎬 da Mesa de Trilhas continuam funcionando de qualquer jeito.": "쓰는 것만 체크하세요. 패널의 🎬 도구가 달라집니다 — 사운드보드의 🎬 키는 어느 쪽이든 그대로 작동합니다.",
    "📡 Transmitir, ⏺ gravar, ⏸ pausa, 📷 câmera virtual e ⏪ replay": "📡 방송, ⏺ 녹화, ⏸ 일시정지, 📷 가상 카메라, ⏪ 리플레이",
    "🎬 Lista de cenas (clique troca a cena)": "🎬 장면 목록(클릭하면 장면이 바뀜)",
    "🎭 Modo estúdio, ✨ mandar o preview ao ar e 🔀 transições": "🎭 스튜디오 모드, ✨ 미리보기를 송출로, 🔀 전환 효과",
    "👁 Mostrar/esconder as fontes da cena que está no ar": "👁 송출 중인 장면의 소스 보이기/숨기기",
    "🔊 Mixer: mudo e volume de cada fonte de áudio": "🔊 믹서: 각 오디오 소스의 음소거와 음량",
    "⏯ Controle de mídia (vídeos e playlists do OBS)": "⏯ 미디어 제어(OBS의 영상과 재생목록)",
    "🎚 Ligar e desligar filtros": "🎚 필터 켜고 끄기",
    "📸 Print da cena, que cai direto nas mídias do programa": "📸 장면 캡처, 바로 프로그램 미디어로 들어감",
    "🗂 Coleções de cenas e 👤 perfis (troca pesada — vem desligado)": "🗂 장면 컬렉션과 👤 프로필(무거운 전환 — 기본은 꺼짐)",
    "— o controle completo do OBS na ferramenta 🎬 do painel: transmitir, gravar (com pausa e marcador de capítulo), câmera virtual, replay, cenas, modo estúdio, transições, mostrar/esconder fontes, mixer de áudio, controle de mídia, filtros, coleções, perfis e print da tela. Tudo isso também vira": "— 패널의 🎬 도구에서 OBS를 전부 제어: 방송, 녹화(일시정지와 챕터 표시 포함), 가상 카메라, 리플레이, 장면, 스튜디오 모드, 전환 효과, 소스 보이기/숨기기, 오디오 믹서, 미디어 제어, 필터, 컬렉션, 프로필, 화면 캡처. 이 모든 것이 또한",
    "botão na Mesa de Trilhas": "사운드보드의 버튼",
    "🎬 Comandar o OBS (cenas, live/gravação, mixer, fontes, filtros, mídias — e as teclas 🎬 da Mesa)": "🎬 OBS 제어(장면, 방송/녹화, 믹서, 소스, 필터, 미디어 — 그리고 사운드보드의 🎬 키)",
    "Como controlo o OBS pelo painel?": "패널에서 OBS를 어떻게 제어하나요?",
    "Ligue 🧪 Labs → 🎬 OBS Studio pelo painel (experimental). Para linkar: no OBS (28+), abra Ferramentas → Configurações do Servidor WebSocket, marque Ativar servidor WebSocket, clique em Mostrar senha das conexões e copie a porta (4455) e a senha para o card do Labs — o passo a passo numerado está lá. Se o OBS estiver em OUTRO computador da rede, ponha o IP dele no campo Endereço (e libere a porta 4455 no firewall daquela máquina). A ferramenta 🎬 do painel comanda tudo: transmitir, gravar (com pausa e marcador de capítulo), câmera virtual, replay buffer, cenas, modo estúdio, transições, mostrar/esconder fontes, mixer de áudio, controle de mídia, filtros, coleções, perfis e print da tela — e cada bloco tem um liga/desliga no card do Labs, para a ferramenta ficar do tamanho que você usa. Tudo dentro do seu computador, sem internet.": "🧪 Labs → 🎬 패널에서 OBS Studio(실험적)를 켜세요. 연결하려면: OBS(28+)에서 도구 → WebSocket 서버 설정을 열고 WebSocket 서버 활성화를 체크한 뒤 연결 정보 표시를 눌러 포트(4455)와 비밀번호를 Labs 카드에 붙여 넣으세요 — 번호가 붙은 안내가 거기 있습니다. OBS가 네트워크의 다른 컴퓨터에 있다면 그 IP를 주소 칸에 넣으세요(그리고 그 컴퓨터의 방화벽에서 4455 포트를 열어 주세요). 패널의 🎬 도구가 전부 제어합니다: 방송, 녹화(일시정지와 챕터 표시 포함), 가상 카메라, 리플레이 버퍼, 장면, 스튜디오 모드, 전환 효과, 소스 보이기/숨기기, 오디오 믹서, 미디어 제어, 필터, 컬렉션, 프로필, 화면 캡처 — 그리고 각 블록마다 Labs 카드에 켜기/끄기가 있어서 도구를 필요한 크기로 맞출 수 있습니다. 전부 내 컴퓨터 안에서, 인터넷 없이.",
    "Dá para transformar as coisas do OBS em botões?": "OBS의 기능을 버튼으로 만들 수 있나요?",
    "Dá — é a tecla 🎬 Ação do OBS na 🎵 Mesa de trilhas. Crie uma tecla, escolha o tipo 🎬 e depois a ação (trocar de cena, gravar, mudo do microfone, mostrar uma fonte, ligar um filtro, tocar uma mídia...). As listas de cenas, fontes e filtros vêm do OBS conectado; o ▶ Testar agora dispara na hora para você conferir. A tecla acende sozinha quando o que ela controla está ligado (gravando, no ar, fonte visível). Essas teclas também entram dentro de um 🎛️ Botão de multi ação: a fila mistura som e comando — trocar de cena, esperar 2s e tocar a vinheta, por exemplo.": "됩니다 — 🎵 사운드보드의 🎬 OBS 동작 키입니다. 키를 만들고 종류 🎬를 고른 다음 동작을 고르세요(장면 전환, 녹화, 마이크 음소거, 소스 보이기, 필터 켜기, 미디어 재생...). 장면·소스·필터 목록은 연결된 OBS에서 옵니다. ▶ 지금 테스트로 바로 실행해 확인할 수 있습니다. 제어 대상이 켜져 있으면(녹화 중, 방송 중, 소스 보임) 키가 스스로 켜집니다. 이 키는 🎛️ 멀티 액션 버튼 안에도 들어갑니다: 줄에서 소리와 명령을 섞을 수 있어요 — 예를 들어 장면을 바꾸고 2초 기다린 뒤 시그널을 재생.",
    // ---------- v0.53: rótulos curtos do editor da tecla 🎬 ----------
    "Cenas": "장면",
    "Fontes": "소스",
    "Cena": "장면",
    "Transição": "전환 효과",
    "Coleção de cenas": "장면 컬렉션",
    "Perfil": "프로필",
    "Parar": "정지",
    "Tocar": "재생",
