    "Direto ao vivo": "바로 라이브로",
    "Encerrar a TRANSMISSÃO no vMix agora? A live sai do ar.": "지금 vMix 방송을 종료할까요? 라이브가 끝납니다.",
    "Iniciar a TRANSMISSÃO no vMix agora? Você entra AO VIVO.": "지금 vMix 방송을 시작할까요? 라이브로 들어갑니다.",
    "Parar a gravação no vMix?": "vMix 녹화를 중지할까요?",
    "Começar a gravar no vMix?": "vMix에서 녹화를 시작할까요?",
    "Abrir o último preset no vMix? Ele recarrega todas as entradas.": "vMix에서 마지막 프리셋을 열까요? 모든 입력을 다시 불러옵니다.",
    "Como controlo o vMix pelo painel?": "패널에서 vMix를 어떻게 제어하나요?",
    "Dá para transformar as coisas do vMix em botões?": "vMix 항목을 버튼으로 만들 수 있나요?",
    "🕒 tempo de membro (YouTube)": "🕒 멤버 기간(YouTube)",
    "meses de membro": "개월 멤버",
    "Meses como membro (0 = membro novo). O YouTube troca o selo em 1, 2, 6, 12, 24, 36... meses.": "멤버 개월 수(0 = 새 멤버). YouTube는 1, 2, 6, 12, 24, 36...개월에 배지를 바꿉니다.",
    "🎯 Faixas — por 💰 valor, 🎨 cor do Super Chat, 🔤 palavra no nome ou 🕒 tempo de membro": "🎯 구간 — 💰 금액, 🎨 슈퍼챗 색상, 🔤 이름의 단어 또는 🕒 멤버 기간",
    "Cada faixa escolhe COMO casar: 💰 a partir de um valor em reais (Super Chat, 🎟️ Super Sticker e 💝 doação, qualquer moeda); 🎨 pelo tom que o próprio YouTube pintou no Super Chat ou no Super Sticker; 🔤 por uma palavra que aparece no espaço do nome (o nome, «Membro», o nível do canal...); ou 🕒 a partir de tantos meses como membro do YouTube (o tempo que o selo do membro mostra: novo, 1, 2, 6, 12, 24 meses...). Quando mais de uma serve, a ordem é: cor → valor → palavra → tempo de membro → comentário comum.": "각 구간은 어떻게 맞출지 정합니다: 💰 헤알 금액 이상(슈퍼챗, 🎟️ 슈퍼 스티커, 💝 후원, 통화 무관); 🎨 YouTube가 슈퍼챗이나 슈퍼 스티커에 칠한 색조; 🔤 이름 영역에 나타나는 단어(이름, \"멤버\", 채널 등급...); 또는 🕒 YouTube 멤버로서 몇 개월 이상(배지가 보여주는 기간: 신규, 1, 2, 6, 12, 24개월...). 여러 개가 맞으면 순서는: 색상 → 금액 → 단어 → 멤버 기간 → 일반 댓글.",
    "🔑 Palavras para participar (até 30)": "🔑 참여 단어(최대 30개)",
    "Com palavras na lista, só entra no sorteio quem digitar uma delas no chat. Lista vazia: todo mundo que fala entra.": "목록에 단어가 있으면 채팅에 그중 하나를 입력한 사람만 추첨에 참여합니다. 목록이 비어 있으면 말하는 모든 사람이 참여합니다.",
    "Com palavras na lista, só entra quem digitar": "목록에 단어가 있으면",
    "uma delas": "그중 하나",
    "no chat — a palavra inteira, sem diferença entre maiúsculas e minúsculas («#sorteio» vale como «sorteio»). Lista vazia = todo mundo que fala entra, como sempre.": "을(를) 채팅에 입력한 사람만 참여합니다 — 단어 전체, 대소문자 구분 없음(\"#추첨\"은 \"추첨\"과 같음). 목록이 비어 있으면 = 늘 그렇듯 말하는 모든 사람이 참여.",
    "ex.: sorteio": "예: 추첨",
    "Nova palavra do sorteio": "새 추첨 단어",
    "Adicionar esta palavra": "이 단어 추가",
    "Tirar esta palavra": "이 단어 제거",
    "Nenhuma palavra — todo mundo que fala no chat entra.": "단어 없음 — 채팅에서 말하는 모든 사람이 참여합니다.",
    "limite de 30 palavras": "30개 단어 제한",
    "Voltar (desfaz o último ajuste do sorteio — vale também para o que foi mexido no botão 🎁 do painel)": "되돌리기(추첨의 마지막 조정 취소 — 패널의 🎁 버튼에서 바꾼 것도 포함)",
    "TUDO do sorteio de volta ao padrão: palavras, fichas, dado, som e resposta (dá para desfazer)": "추첨의 모든 것을 기본값으로: 단어, 티켓, 주사위, 소리, 응답(되돌릴 수 있음)",
    "📏 Pontilhado do modo medida": "📏 측정 모드 점선",
    "Quanto o contorno pontilhado branco aparece enquanto você digita no seletor manual (modo medida). Preferência deste navegador.": "수동 크기 입력란에 입력하는 동안(측정 모드) 흰 점선 윤곽이 얼마나 잘 보이는지. 이 브라우저의 설정입니다.",
    "Mais visível": "더 잘 보이게",
    "Bem visível": "아주 잘 보이게",
    "📺 Por rede — cada uma pode vestir o seu próprio molde de comentário comum": "📺 네트워크별 — 각 네트워크가 일반 댓글용 자체 템플릿을 입을 수 있습니다",
    "Um molde marcado como exclusivo de uma rede (▶️ 💜 🟢 💙) nunca veste comentário de outra. Aqui você diz o que cada rede veste quando nenhuma faixa casa: o comum acima, um molde só dela ou o visual ao vivo (sem molde).": "한 네트워크 전용(▶️ 💜 🟢 💙)으로 표시된 템플릿은 다른 네트워크의 댓글을 절대 입지 않습니다. 여기서 어떤 구간에도 맞지 않을 때 각 네트워크가 무엇을 입을지 정합니다: 위의 일반 템플릿, 그 네트워크만의 템플릿 또는 라이브 모습(템플릿 없음).",
    "💰 Super Chat ou doação que não casa com faixa nenhuma veste": "💰 어떤 구간에도 맞지 않는 슈퍼챗이나 후원이 입는 것",
    "— o mesmo do comentário comum —": "— 일반 댓글과 동일 —",
    "— o visual ao vivo (sem molde) —": "— 라이브 모습(템플릿 없음) —",
    "— o mesmo do comentário comum da rede —": "— 해당 네트워크의 일반 댓글과 동일 —",
    "⚠️ O visual ao vivo (quem veste tudo que não casa com molde) está com a arte «{arte}». Se a ideia era a arte só nos moldes, tire-a do visual ao vivo:": "⚠️ 라이브 모습(템플릿에 맞지 않는 모든 것이 입는 것)에 아트 \"{arte}\"가 있습니다. 아트를 템플릿에만 쓸 생각이었다면 라이브 모습에서 빼세요:",
    "🎭 Editando:": "🎭 편집 중:",
    "Qual visual do destaque esta aba ajusta: o visual ao vivo (sem molde) ou um molde salvo. É o mesmo seletor 🎭 Editando do 🖱️ Organizar a tela.": "이 탭이 조정하는 하이라이트 모습: 라이브 모습(템플릿 없음) 또는 저장된 템플릿. 🖱️ 화면 정리의 🎭 편집 중 선택기와 같습니다.",
    "⚠️ O comentário no ar está vestindo o molde «{molde}» pelo 🎭 automático — o que você ajusta aqui vai para o visual ao vivo, que a tela NÃO está mostrando agora. Abra o molde para mudar o que está na tela.": "⚠️ 방송 중인 댓글은 🎭 자동으로 \"{molde}\" 템플릿을 입고 있습니다 — 여기서 조정한 것은 라이브 모습으로 가지만, 화면은 지금 그것을 보여주고 있지 않습니다. 화면의 것을 바꾸려면 템플릿을 여세요.",
    "⚠️ O comentário no ar está vestindo o molde «{molde}» pelo 🎭 automático — você está ajustando «{editando}». Abra «{molde}» para mudar o que está na tela.": "⚠️ 방송 중인 댓글은 🎭 자동으로 \"{molde}\" 템플릿을 입고 있습니다 — 지금 \"{editando}\"을(를) 조정 중입니다. 화면의 것을 바꾸려면 \"{molde}\"을(를) 여세요.",
    "🎭 Abrir «{molde}»": "🎭 \"{molde}\" 열기",
    "✍️ Formatação dos textos": "✍️ 텍스트 서식",
    "Qual texto": "어떤 텍스트",
