    "✍️ «{peca}» é imagem ou caixa, não tem letra para formatar — clique numa peça com texto (nome, texto, valor, títulos, números...).": "✍️ \"{peca}\"은(는) 이미지 또는 상자라 서식을 줄 글자가 없습니다 — 텍스트가 있는 조각(이름, 텍스트, 금액, 제목, 숫자...)을 클릭하세요.",
