    "dele (quem fica por cima — vale na live de verdade). O 👁 esconde só aqui no editor; o 🔒 trava contra esbarrões.": "를 바꿉니다(누가 위에 오는지 — 진짜 방송에 적용). 👁는 이 편집기 안에서만 숨기고, 🔒는 실수로 건드리는 걸 막습니다.",
    "🎭 Troca automática — cada comentário destacado veste o perfil certo sozinho": "🎭 자동 전환 — 강조된 댓글마다 맞는 프로필을 저절로 입습니다",
    "Ligar a troca automática": "자동 전환 켜기",
    "— um seletor para cada overlay/widget. Para moldura de tela inteira, crie em 1920×1080 com fundo transparente (PNG ou WebM). O fundo do comentário em destaque se escolhe lá em cima, na linha": "— 오버레이/위젯마다 선택기 하나. 전체 화면 프레임은 1920×1080, 투명 배경(PNG나 WebM)으로 만드세요. 강조 댓글의 배경은 위쪽",
    "— e com um molde em edição, a arte escolhida grava DENTRO do perfil.": "줄에서 고릅니다 — 그리고 틀을 편집 중이면 고른 아트가 프로필 안에 저장됩니다.",
    "Veste o perfil escolhido AGORA no visual ao vivo do destaque (dá para desfazer no ◀)": "고른 프로필을 지금 바로 강조의 라이브 모습에 입힙니다(◀로 되돌릴 수 있음)",
    "nome do perfil novo": "새 프로필 이름",
