    "⏳ Tempo de tela (enquanto está visível)": "⏳ 화면 시간(표시되는 동안)",
    "— sem som —": "— 사운드 없음 —",
    "🔁 Repetir na tela": "🔁 화면에 있는 동안 반복",
    "🔊 No overlay e no painel": "🔊 오버레이와 패널 모두",
    "📺 Só no overlay (a live ouve)": "📺 오버레이만(방송에 들림)",
    "🖥️ Só no painel (só eu ouço)": "🖥️ 패널만(나만 들림)",
    "Adiantar (negativo: pula o começo do áudio) ou atrasar (positivo: espera antes de tocar), em segundos": "앞당기기(음수: 오디오 앞부분 건너뜀) 또는 늦추기(양수: 재생 전 대기), 초 단위",
    "Repetir enquanto o overlay estiver na tela": "오버레이가 화면에 있는 동안 반복",
    "Quanto tempo o áudio toca (0 = até o fim do arquivo)": "오디오 재생 시간(0 = 파일 끝까지)",
    "Maximizar / restaurar (estilo janela)": "최대화/복원(창 스타일)",
    "Opções desta janela": "이 창의 옵션",
    "Chegar já aberta quando outro navegador abrir (senão vira um chip minimizado)": "다른 브라우저가 열면 처음부터 열린 채로 도착(아니면 최소화 칩이 됩니다)",
    "Sincronizar com os outros navegadores (desligado: esta janela ignora o que vem deles)": "다른 브라우저와 동기화(끄면 이 창은 거기서 오는 것을 무시합니다)",
    "Fechar": "닫기",
    "Encaixar de volta na barra de ferramentas": "도구 모음에 다시 끼우기",
    "Fechar esta instância (some daqui e da tela do público)": "이 인스턴스 닫기(여기와 시청자 화면에서 사라집니다)",
    "Permitir várias instâncias ao mesmo tempo (vale para todos: painel e tela do público)": "여러 인스턴스 동시 허용(모두에게 적용: 패널과 시청자 화면)",
    "Tempo do timer (dias, horas, minutos e segundos)": "타이머 시간(일·시·분·초)",
    "Dias": "일",
    "Horas": "시간",
    "⏰ Sumir sozinho (deixe em 00 o que não quiser usar)": "⏰ 저절로 사라지기(쓰지 않을 칸은 00으로 두세요)",
    "O aviso sai quando o relógio bater com os números preenchidos (o que ficar em 00 vale para qualquer valor)": "공지는 시계가 입력한 숫자와 일치할 때 사라집니다(00으로 남긴 칸은 모든 값에 해당)",
    "O aviso sai quando faltar esse tempo no timer": "공지는 타이머 남은 시간이 이만큼일 때 사라집니다",
    "Dia (DD)": "일(DD)",
    "Mês (MM)": "월(MM)",
    "Ano (AAAA)": "년(YYYY)",
    "Hora (HH)": "시(HH)",
    "Minuto (MM)": "분(MM)",
    "Segundo (SS)": "초(SS)",
    "🕐 sai quando o relógio chegar na data/hora preenchida · ⏳ sai quando faltar esse tempo no timer. Disparou uma vez, os números voltam a 00.": "🕐 시계가 입력한 날짜/시각에 도달하면 사라집니다 · ⏳ 타이머 남은 시간이 이만큼이면 사라집니다. 한 번 발동하면 숫자는 00으로 돌아갑니다.",
    "Se o ⏳ Timer estiver combinado com os Avisos, o recado também sai sozinho quando o tempo acabar.": "⏳ 타이머가 공지와 연동되어 있으면 시간이 끝날 때도 메시지가 저절로 사라집니다.",
    "Minimizar (vira um chip na barra de cima)": "최소화(상단 바의 칩이 됩니다)",
    "🎬 OBS Studio Remoto": "🎬 OBS Studio 원격",
    "🎵 Mesa de Trilhas": "🎵 트랙 데크",
    "A conexão e o controle completo do OBS Studio pelo painel. Esta página fica disponível enquanto o seletor 🎬 estiver ligado na aba 🧪 Labs.": "패널에서의 OBS Studio 연결과 완전한 제어. 이 페이지는 🧪 Labs 탭의 🎬 스위치가 켜져 있는 동안 사용할 수 있습니다.",
    "As trilhas, a grade de botões e a importação do Stream Deck. Esta página fica disponível enquanto o seletor 🎵 estiver ligado na aba 🧪 Labs.": "트랙, 버튼 그리드, Stream Deck 가져오기. 이 페이지는 🧪 Labs 탭의 🎵 스위치가 켜져 있는 동안 사용할 수 있습니다.",
    "⚙️ Ligado, a configuração completa mora na página «🎬 OBS Studio Remoto» do menu à esquerda (logo depois de 🎨 Temas).": "⚙️ 켜면 전체 설정은 왼쪽 메뉴의 «🎬 OBS Studio 원격» 페이지에 있습니다(🎨 테마 바로 다음).",
    "⚙️ Ligada, a configuração completa mora na página «🎵 Mesa de Trilhas» do menu à esquerda (logo depois de 🎨 Temas).": "⚙️ 켜면 전체 설정은 왼쪽 메뉴의 «🎵 트랙 데크» 페이지에 있습니다(🎨 테마 바로 다음).",
    "A porta e a senha ficam na página «🎬 OBS Studio Remoto» das configurações.": "포트와 비밀번호는 설정의 «🎬 OBS Studio 원격» 페이지에 있습니다.",
    "⌨️ Atalhos do OBS": "⌨️ OBS 단축키",
    "Qualquer coisa com atalho no OBS (até de plugin) dispara daqui — é o coringa do que ainda não tem botão próprio.": "OBS에서 단축키가 있는 것이라면(플러그인 것도) 여기서 발동됩니다 — 아직 전용 버튼이 없는 것들의 만능 카드입니다.",
    "Disparar este atalho no OBS": "이 단축키를 OBS에서 발동",
    "Há quanto tempo a transmissão está no ar": "방송이 시작된 지 얼마나 됐는지",
    "Há quanto tempo a gravação está rodando": "녹화가 시작된 지 얼마나 됐는지",
    "Quadros por segundo que o OBS está desenhando": "OBS가 그리는 초당 프레임 수",
    "Uso de processador pelo OBS": "OBS의 프로세서 사용률",
    "Memória usada pelo OBS": "OBS가 사용 중인 메모리",
    "Espaço livre no disco das gravações": "녹화 디스크의 남은 공간",
    "Quadros perdidos (desenho + saída + rede) — sinal de aperto na máquina ou na internet": "손실 프레임(렌더+출력+네트워크) — 컴퓨터나 인터넷이 힘들다는 신호",
    "📊 Saúde do OBS: fps, CPU, memória, disco, quadros perdidos e tempos de transmissão/gravação": "📊 OBS 건강: fps, CPU, 메모리, 디스크, 손실 프레임, 방송/녹화 시간",
    "⌨️ Disparar atalhos do OBS por nome — o coringa do que não tem botão próprio (vem desligado)": "⌨️ 이름으로 OBS 단축키 발동 — 전용 버튼이 없는 것들의 만능 카드(기본 꺼짐)",
    "🎬 Criar teclas do OBS na Mesa (escolha o que quiser)": "🎬 데크에 OBS 키 만들기(원하는 것 선택)",
    "Marque os recursos do seu OBS e aperte ➕: cada um vira uma tecla DE VERDADE na Mesa — dá para mover, renomear, colorir e apagar como qualquer outra. Depois de criar, é só arrastar cada tecla para a célula que quiser.": "OBS의 리소스를 체크하고 ➕를 누르세요: 각각이 사운드보드의 진짜 키가 됩니다 — 다른 키처럼 이동, 이름 변경, 색상 지정, 삭제가 가능합니다. 만든 뒤에는 각 키를 원하는 칸으로 끌어다 놓기만 하면 됩니다.",
    "➕ Criar as teclas marcadas": "➕ 체크한 키 만들기",
    "Conecte o 🎬 OBS Studio (página OBS Studio Remoto) para listar os recursos dele aqui.": "🎬 OBS Studio를 연결하면(OBS Studio 원격 페이지) 리소스가 여기 나열됩니다.",
