    // 🎞️ v0.129: mídia direta (URL ou arquivo do computador, direto para a tela)
    "Mídia direta: imagem, vídeo ou áudio de uma URL ou do computador": "직접 미디어: URL 또는 컴퓨터의 이미지, 영상, 오디오",
    "🎞️ Mídia direta": "🎞️ 직접 미디어",
    "Cole a URL (YouTube, TikTok, Instagram, Discord, arquivo…)": "URL 붙여넣기 (YouTube, TikTok, Instagram, Discord, 파일…)",
    "Carregar a mídia (a tela fica como está: use o 👁️ para mostrar)": "미디어 불러오기 (화면은 그대로: 보여주려면 👁️ 사용)",
    "Carregar": "불러오기",
    "Carregar e já mostrar na tela do público": "불러와서 바로 시청자 화면에 보여주기",
    "📂 Do computador (o arquivo fica onde está — nada sobe para a biblioteca)": "📂 컴퓨터에서 (파일은 있던 자리에 그대로 — 라이브러리에 올라가지 않음)",
    "Caminho do arquivo no computador": "컴퓨터에 있는 파일 경로",
    "Navegar pelas pastas do computador para escolher o arquivo": "컴퓨터의 폴더를 둘러보며 파일 선택",
    "📂 Procurar": "📂 찾아보기",
    "Usar este arquivo e já mostrar na tela": "이 파일을 사용하고 바로 화면에 보여주기",
    "Usar": "사용",
    "Voltar para a pasta de cima": "상위 폴더로 돌아가기",
